import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Upload, X, Globe, ArrowLeft, User, BookOpen, Cpu, ShieldCheck, Loader2 } from 'lucide-react';

const CandidateRegistration = () => {
  const navigate = useNavigate();
  const bgImage = "https://i.pinimg.com/1200x/3d/da/0d/3dda0d2769ba87e3b59597ba56f6548e.jpg";

  // State for dynamic skills
  const [skills, setSkills] = useState(['React.js', 'Tailwind CSS']);
  const [skillInput, setSkillInput] = useState("");
  const [isRegistering, setIsRegistering] = useState(false);

  // Handler for adding skills
  const handleSkillKeyDown = (e) => {
    if (e.key === 'Enter' || e.key === ',') {
      e.preventDefault();
      const newSkill = skillInput.trim().replace(/,/g, '');
      if (newSkill && !skills.includes(newSkill)) {
        setSkills([...skills, newSkill]);
        setSkillInput("");
      }
    } else if (e.key === 'Backspace' && !skillInput && skills.length > 0) {
      setSkills(skills.slice(0, -1));
    }
  };

  const removeSkill = (indexToRemove) => {
    setSkills(skills.filter((_, index) => index !== indexToRemove));
  };

  // Handler for form submission
const handleFinalRegister = async (e) => {
  e.preventDefault();
  setIsRegistering(true);

  const formData = {
    user_name: e.target[0].value,
    email: e.target[1].value,
    password: e.target[2].value,
    role: "student",
    university: e.target[4].value,
    degree: e.target[5].value,
    skills: skills   // from your state
  };

  try {
    const res = await fetch("http://localhost:5000/api/auth/register", {
      method: "POST",
      headers: {
        "Content-Type": "application/json"
      },
      body: JSON.stringify(formData)
    });

    const data = await res.json();

    if (res.ok) {
      alert("Student Registered Successfully ✅");
      navigate("/candidate/dashboard");
    } else {
      alert(data.message || "Registration Failed ❌");
    }

  } catch (err) {
    console.error(err);
    alert("Server Error ❌");
  } finally {
    setIsRegistering(false);
  }
};

  return (
    <div className="min-h-screen flex flex-col items-center py-12 px-4 relative overflow-hidden font-sans"
      style={{ 
        backgroundImage: `linear-gradient(rgba(15, 23, 42, 0.9), rgba(88, 28, 135, 0.8)), url(${bgImage})`, 
        backgroundSize: 'cover', 
        backgroundAttachment: 'fixed' 
      }}>
      
      {/* Decorative Glow Elements */}
      <div className="absolute top-0 -left-20 w-96 h-96 bg-purple-500/20 rounded-full blur-[120px] pointer-events-none"></div>
      <div className="absolute bottom-0 -right-20 w-96 h-96 bg-blue-500/20 rounded-full blur-[120px] pointer-events-none"></div>

      {/* Header / Nav */}
      <div className="w-full max-w-4xl flex justify-between items-center mb-8 z-10">
        <div className="flex items-center gap-2 text-white font-black text-2xl tracking-tighter">
          <div className="bg-white/10 p-2 rounded-lg backdrop-blur-md border border-white/20">
            <Globe size={24} className="text-purple-400" />
          </div>
          Talent<span className="text-purple-400">Pool</span>
        </div>
        <button 
          onClick={() => navigate('/register')} 
          className="flex items-center gap-2 text-white/60 hover:text-white font-bold text-xs uppercase tracking-widest transition-all"
        >
          <ArrowLeft size={16} /> Back to Selection
        </button>
      </div>

      {/* Main Glass Card */}
      <div className="bg-white/10 backdrop-blur-2xl w-full max-w-3xl rounded-[3rem] shadow-2xl border border-white/10 overflow-hidden z-10 animate-in fade-in zoom-in duration-700">
        
        {/* Card Header */}
        <div className="p-10 border-b border-white/10 text-center bg-white/5">
          <div className="inline-flex items-center gap-2 bg-purple-500/20 px-3 py-1 rounded-full border border-purple-500/30 mb-4">
            <ShieldCheck size={14} className="text-purple-400" />
            <span className="text-[10px] font-black text-purple-200 uppercase tracking-widest">Security Level: High</span>
          </div>
          <h1 className="text-3xl font-black text-white tracking-tight">Candidate Registration</h1>
          <p className="text-purple-200/60 text-sm mt-2 font-medium">Build your professional identity to get matched with top recruiters.</p>
        </div>

        <form className="p-10 space-y-10" onSubmit={handleFinalRegister}>
          
          {/* Section 1: Account */}
          <section className="space-y-6">
            <div className="flex items-center gap-3 text-purple-400 font-black text-xs uppercase tracking-[0.2em]">
              <User size={18} /> Personal Identity
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
              <input type="text" placeholder="Full Legal Name" className="glass-input" required />
              <input type="email" placeholder="Professional Email" className="glass-input" required />
              <input type="password" placeholder="Create Password" className="glass-input" required />
              <input type="password" placeholder="Confirm Password" className="glass-input" required />
            </div>
          </section>

          {/* Section 2: Education */}
          <section className="space-y-6">
            <div className="flex items-center gap-3 text-purple-400 font-black text-xs uppercase tracking-[0.2em]">
              <BookOpen size={18} /> Academic Background
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
              <input type="text" placeholder="University / Institution" className="glass-input" />
              <input type="text" placeholder="Degree / Field of Study" className="glass-input" />
            </div>
          </section>

          {/* Section 3: Skills (INTERACTIVE) */}
          <section className="space-y-6">
            <div className="flex items-center gap-3 text-purple-400 font-black text-xs uppercase tracking-[0.2em]">
              <Cpu size={18} /> Expertise & Skills
            </div>
            <div className="flex flex-wrap gap-3 p-5 border border-white/10 rounded-[1.5rem] bg-white/5 min-h-[100px] transition-all focus-within:border-purple-500/50">
              {skills.map((skill, index) => (
                <div 
                  key={index} 
                  className="bg-purple-600/30 text-white px-4 py-1.5 rounded-full text-xs font-bold flex items-center gap-2 border border-purple-400/30 animate-in zoom-in duration-300"
                >
                  {skill}
                  <button type="button" onClick={() => removeSkill(index)} className="hover:text-purple-200 transition-colors">
                    <X size={14} />
                  </button>
                </div>
              ))}
              <input 
                type="text" 
                value={skillInput}
                onChange={(e) => setSkillInput(e.target.value)}
                onKeyDown={handleSkillKeyDown}
                placeholder={skills.length === 0 ? "Type a skill and hit Enter" : "Add more..."}
                className="bg-transparent outline-none text-white text-sm flex-1 min-w-[150px] placeholder:text-white/20"
              />
            </div>
          </section>

          {/* Section 4: Resume */}
          <section className="space-y-6">
            <div className="flex items-center gap-3 text-purple-400 font-black text-xs uppercase tracking-[0.2em]">
              <ShieldCheck size={18} /> Verification Documents
            </div>
            <div className="border-2 border-dashed border-white/10 rounded-[2rem] p-12 flex flex-col items-center justify-center bg-white/5 hover:bg-white/10 transition-all cursor-pointer group">
              <div className="bg-purple-500/20 p-4 rounded-2xl text-purple-400 mb-4 group-hover:scale-110 transition-transform">
                <Upload size={32} />
              </div>
              <p className="text-white font-bold tracking-tight">Upload Professional Resume</p>
              <p className="text-xs text-white/40 mt-1 uppercase font-black tracking-widest">PDF format preferred (Max 5MB)</p>
              <input type="file" className="hidden" id="resume-upload" accept=".pdf,.doc,.docx" />
              <label htmlFor="resume-upload" className="mt-4 px-6 py-2 bg-white/10 hover:bg-white/20 text-white text-[10px] font-black rounded-full transition-all cursor-pointer border border-white/10 uppercase tracking-widest">Select File</label>
            </div>
          </section>

          {/* Submit Button with Loading State */}
          <button 
            type="submit" 
            disabled={isRegistering}
            className="w-full bg-gradient-to-r from-purple-600 to-indigo-600 text-white font-black py-5 rounded-2xl shadow-xl hover:brightness-110 transition-all transform active:scale-[0.98] tracking-[0.2em] text-sm uppercase flex items-center justify-center gap-3"
          >
            {isRegistering ? (
              <>
                <Loader2 className="animate-spin" size={20} />
                Encrypting Profile...
              </>
            ) : (
              "Create Professional Profile"
            )}
          </button>
        </form>
      </div>

      <style>{`
        .glass-input {
          width: 100%; 
          padding: 1.1rem 1.5rem; 
          background: rgba(255, 255, 255, 0.05);
          border: 1px solid rgba(255, 255, 255, 0.1); 
          border-radius: 1.25rem;
          color: white; 
          font-size: 0.9rem; 
          font-weight: 500;
          outline: none; 
          transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
        }
        .glass-input:focus {
          border-color: #a855f7; 
          background: rgba(255, 255, 255, 0.1);
          box-shadow: 0 10px 25px -5px rgba(168, 85, 247, 0.3);
          transform: translateY(-2px);
        }
        .glass-input::placeholder { color: rgba(255, 255, 255, 0.2); }
      `}</style>
    </div>
  );
};

export default CandidateRegistration;
